"""Al-Mu'allim live voice studio.

A live backend is required; see README for launch/configuration. The iframe receives
only a temporary Realtime token and never sees the OpenAI server key.
"""
import html
import json
import os

import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title="Live Studio · Al-Mu'allim", page_icon="🎙️", layout="wide")
st.markdown("""
<style>
.stApp{background:linear-gradient(145deg,#faf7ef,#eff3ec 68%,#f7f1e4)}
h1,h2,h3{font-family:Georgia,'Times New Roman',serif;color:#27372e}
[data-testid=stSidebar]{background:#edf1e9}
</style>
""", unsafe_allow_html=True)
st.title("🎙️ Live Studio")
st.caption("Live voice depends on your configured audio backend. Qur'an word matching is a transcript aid, not certified pronunciation or Tajweed assessment.")

api_url = os.getenv("AL_MUALLIM_API_URL", "http://localhost:8000").rstrip("/")
if not os.getenv("AL_MUALLIM_API_URL"):
    st.warning("Set AL_MUALLIM_API_URL to the HTTPS URL of the live backend in deployment. Microphone access requires HTTPS (localhost is allowed for development).")

portrait_options = {"Male": "IMG_6146.jpeg", "Female": "IMG_6147.jpeg"}
with st.sidebar:
    st.subheader("Session")
    teacher = st.radio("Teacher voice and portrait", ["Male", "Female"], horizontal=True)
    st.image(f"https://raw.githubusercontent.com/Abia2746/ReadandMemorisetheQuran/main/{portrait_options[teacher]}", width=120, caption=f"{teacher} teacher portrait")
    st.caption("The selected portrait is illustrative; the generated voice is not the person pictured.")
    reference = st.text_area("Ayah text for word alignment (optional)", height=110, placeholder="Paste the Arabic ayah you are reciting")

safe_api = json.dumps(api_url)
safe_teacher = json.dumps(teacher)
safe_reference = json.dumps(reference)
html_doc = r"""<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#fdfbf6;color:#29372d;font:15px system-ui,sans-serif}.wrap{padding:18px;border:1px solid #e3dcc8;border-radius:20px;background:linear-gradient(150deg,#fffefa,#f1f3eb);box-shadow:0 12px 35px #39331a12}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.btn{border:0;border-radius:999px;background:#a98c45;color:white;padding:12px 18px;font-weight:650;cursor:pointer}.btn.secondary{background:#657b68}.btn:disabled{opacity:.5;cursor:default}.status{margin:12px 0;color:#526455;min-height:22px}.avatar{width:64px;height:64px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#e7d8aa,#91a38d 65%,#536b59);box-shadow:0 0 0 4px #fff,0 0 0 6px #c9ab63;transition:transform .2s,box-shadow .2s}.avatar.talking{transform:scale(1.09);box-shadow:0 0 0 4px #fff,0 0 0 8px #c9ab63,0 0 30px #c9ab6370}.panel{margin-top:14px;padding:14px;border:1px solid #e8e1d0;border-radius:14px;background:#fffefa}.words{direction:rtl;text-align:right;font-family:'Amiri','Noto Naskh Arabic',serif;font-size:28px;line-height:2}.word{display:inline-block;margin:2px 3px;padding:2px 6px;border-radius:8px;transition:background .22s,transform .22s}.word.heard{background:#e5eddf;color:#34533b}.word.uncertain{background:#f8ecc8;color:#785b18}.word.missed{background:#f3e1dc;color:#9b4537}.small{font-size:12px;color:#777}.meter{height:8px;background:#e8e5da;border-radius:8px;overflow:hidden;width:150px}.meter i{height:100%;display:block;width:0;background:#78906f;transition:width .1s}.transcript{min-height:24px;color:#4f6252}.error{color:#a63d32}.live{color:#437750;font-weight:700}@media(max-width:600px){.wrap{padding:12px}.words{font-size:23px}}
</style></head><body><main class="wrap"><div class="row"><div id="avatar" class="avatar" aria-label="Animated teacher avatar"></div><div><b>Al-Mu'allim · Live teacher</b><div class="small">Generated speech · speak to interrupt</div></div><div style="flex:1"></div><div class="meter" title="Microphone level"><i id="level"></i></div></div><div class="row" style="margin-top:16px"><button class="btn" id="teacher">Start voice teacher</button><button class="btn secondary" id="recite">Start live recitation</button><button class="btn secondary" id="stop" disabled>Stop microphone</button></div><div id="status" class="status">Ready. Allow microphone access when prompted.</div><div class="panel"><b>Recitation alignment</b><div class="small">Interim recognition may revise earlier words. A match does not assess makharij, vowels, madd or Tajweed.</div><div id="words" class="words" dir="rtl"></div><div id="transcript" class="transcript" aria-live="polite"></div><div id="matchnote" class="small"></div></div><audio id="remote" autoplay></audio></main><script>
const API=__API__,TEACHER=__TEACHER__,REFERENCE=__REFERENCE__;
const statusEl=document.getElementById('status'),teacherBtn=document.getElementById('teacher'),reciteBtn=document.getElementById('recite'),stopBtn=document.getElementById('stop'),avatar=document.getElementById('avatar'),remote=document.getElementById('remote');
let pc=null, mic=null, socket=null, audioContext=null, analyser=null, raf=0, sourceNode=null, workletUrl=null, reciting=false, transcriptFinal='';
function status(s,bad=false){statusEl.textContent=s;statusEl.className='status'+(bad?' error':'')}
function normalize(s){return s.replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g,'').replace(/[إأآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[^\u0621-\u064A\s]/g,' ').trim().split(/\s+/).filter(Boolean)}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function paintAlignment(text,final){const root=document.getElementById('words');const expected=normalize(REFERENCE),heard=normalize(text);document.getElementById('transcript').textContent=text||'Waiting for Arabic speech…';if(!expected.length){root.textContent='Add the target ayah in the sidebar to show word alignment.';return}let i=0;root.innerHTML=expected.map((w,index)=>{let state='';if(i<heard.length&&heard[i]===w){state='heard';i++}else if(i<heard.length&&heard[i].slice(0,2)===w.slice(0,2)&&Math.abs(heard[i].length-w.length)<=1){state='uncertain';i++}else if(final)state='missed';return '<span class="word '+state+'">'+escapeHtml(REFERENCE.trim().split(/\s+/)[index]||w)+'</span>'}).join(' ');document.getElementById('matchnote').textContent=final?'Final transcript alignment only; shaded omissions are tentative recognition mismatches, not confirmed recitation mistakes.':'Interim match · recognition is still changing.'}
function animateLevel(stream){audioContext=new(window.AudioContext||window.webkitAudioContext)();analyser=audioContext.createAnalyser();analyser.fftSize=256;sourceNode=audioContext.createMediaStreamSource(stream);sourceNode.connect(analyser);const buf=new Uint8Array(analyser.frequencyBinCount);const tick=()=>{analyser.getByteTimeDomainData(buf);let sum=0;for(const x of buf)sum+=(x-128)*(x-128);const rms=Math.sqrt(sum/buf.length)/128;document.getElementById('level').style.width=Math.min(100,Math.round(rms*260))+'%';if(reciting||pc)avatar.classList.toggle('talking',rms>.035);raf=requestAnimationFrame(tick)};tick()}
async function startTeacher(){try{teacherBtn.disabled=true;status('Connecting to live teacher…');const tokenRes=await fetch(API+'/api/realtime/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({teacher:TEACHER,ayah:REFERENCE})});if(!tokenRes.ok)throw Error((await tokenRes.json()).detail||'Could not create a voice session');const {client_secret}=await tokenRes.json();pc=new RTCPeerConnection();pc.ontrack=e=>{remote.srcObject=e.streams[0]};pc.onconnectionstatechange=()=>{if(pc.connectionState==='connected')status('Teacher connected · speak naturally; starting to talk interrupts the reply.');if(['failed','disconnected'].includes(pc.connectionState))status('Voice connection lost. Stop and reconnect, and check network/microphone permissions.',true)};const dc=pc.createDataChannel('oai-events');dc.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type?.includes('error'))status(d.error?.message||'Voice session error',true);if(d.type==='input_audio_buffer.speech_started')status('Listening…');if(d.type==='response.audio.started')avatar.classList.add('talking');if(d.type==='response.audio.done')avatar.classList.remove('talking')}catch{}};mic=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});animateLevel(mic);mic.getTracks().forEach(t=>pc.addTrack(t,mic));const offer=await pc.createOffer();await pc.setLocalDescription(offer);const answer=await fetch('https://api.openai.com/v1/realtime/calls',{method:'POST',headers:{Authorization:'Bearer '+client_secret,'Content-Type':'application/sdp'},body:offer.sdp});if(!answer.ok)throw Error('Realtime connection was rejected ('+answer.status+'). Check model/account access.');await pc.setRemoteDescription({type:'answer',sdp:await answer.text()});stopBtn.disabled=false}catch(e){status(e.name==='NotAllowedError'?'Microphone permission denied. Allow microphone access in browser settings and reload.':(e.message||'Could not start voice teacher.'),true);stopAll()}}
function audioWorkletSource(){return `class PCMProcessor extends AudioWorkletProcessor{process(inputs){const x=inputs[0]?.[0];if(x){const ratio=sampleRate/16000;const n=Math.floor(x.length/ratio);const out=new Int16Array(n);for(let i=0;i<n;i++){const v=x[Math.min(x.length-1,Math.floor(i*ratio))];out[i]=Math.max(-32768,Math.min(32767,Math.round(v<0?v*32768:v*32767)))}this.port.postMessage(out.buffer,[out.buffer])}return true}}registerProcessor('pcm-processor',PCMProcessor)`}
async function startRecitation(){try{reciteBtn.disabled=true;status('Requesting microphone…');mic=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:false,noiseSuppression:false,autoGainControl:false}});reciting=true;animateLevel(mic);const wsUrl=API.replace(/^http/,'ws')+'/ws/recitation';socket=new WebSocket(wsUrl);socket.binaryType='arraybuffer';socket.onopen=async()=>{try{audioContext=new(window.AudioContext||window.webkitAudioContext)();await audioContext.audioWorklet.addModule(URL.createObjectURL(new Blob([audioWorkletSource()],{type:'application/javascript'})));sourceNode=audioContext.createMediaStreamSource(mic);const node=new AudioWorkletNode(audioContext,'pcm-processor');node.port.onmessage=e=>{if(socket?.readyState===WebSocket.OPEN)socket.send(e.data)};sourceNode.connect(node);status('Live Arabic recognition connected · recite at a natural pace.');stopBtn.disabled=false}catch(e){status('Could not start audio processing: '+e.message,true);stopAll()}};socket.onmessage=e=>{const d=JSON.parse(e.data);if(d.type==='error'){status(d.message,true);return}if(d.type==='transcript'){const text=(transcriptFinal+' '+d.text).trim();paintAlignment(text,d.final);if(d.final){transcriptFinal=(text+' ').trim();paintAlignment(transcriptFinal,true)} }};socket.onerror=()=>status('Recognition connection failed. Check the backend URL, TLS and network.',true);socket.onclose=()=>{if(reciting)status('Recognition disconnected. Check backend and Google Speech credentials.',true)}}catch(e){status(e.name==='NotAllowedError'?'Microphone permission denied. Allow microphone access in browser settings and reload.':(e.message||'Could not start recitation.'),true);stopAll()}}
function stopAll(){reciting=false;cancelAnimationFrame(raf);if(socket){socket.close();socket=null}if(pc){pc.close();pc=null}if(mic){mic.getTracks().forEach(t=>t.stop());mic=null}if(audioContext){audioContext.close().catch(()=>{});audioContext=null}sourceNode=null;avatar.classList.remove('talking');teacherBtn.disabled=false;reciteBtn.disabled=false;stopBtn.disabled=true;document.getElementById('level').style.width='0%';status('Session stopped.')}
teacherBtn.onclick=startTeacher;reciteBtn.onclick=startRecitation;stopBtn.onclick=stopAll;window.addEventListener('beforeunload',stopAll);document.getElementById('words').textContent=REFERENCE?REFERENCE:'Add the target ayah in the sidebar to show alignment.';
</script></body></html>"""
html_doc = html_doc.replace("__API__", safe_api).replace("__TEACHER__", safe_teacher).replace("__REFERENCE__", safe_reference)
components.html(html_doc, height=610, scrolling=True)
st.markdown("**Feedback limits:** Live word highlighting follows Google Speech recognition hypotheses and can revise or omit words. It is not proof of correct pronunciation. Tajweed rules such as ghunnah, madd and makharij require a qualified human teacher; this page deliberately does not label them as machine-confirmed errors.")
